function themeFromPreset(presetId) {
  const p = getThemePreset(presetId);
  return {
    mode: p.mode,
    colors: { ...p.colors },
    fonts: { heading: "inter-sora", body: "inter-sora", arabic: "kufi" },
    radius: p.radius,
    buttonStyle: p.buttonStyle,
    cardStyle: p.cardStyle,
    density: p.density
  };
}
function buildSections(types, brand, contentOverrides = {}, variants = {}) {
  return types.map((type) => {
    const defaults = sectionDefaults(type, brand);
    const override = contentOverrides[type] ?? {};
    return {
      id: uid(),
      type,
      hidden: false,
      variant: variants[type],
      content: deepMerge(defaults, override)
    };
  });
}
function buildPages(tpl2, sections, names) {
  return names.map((p) => {
    const occurrence = /* @__PURE__ */ new Map();
    const indexOf = (t) => {
      const seen = occurrence.get(t) ?? 0;
      occurrence.set(t, seen + 1);
      const found = sections.filter((s) => s.type === t)[seen];
      return found?.id;
    };
    return {
      id: uid(),
      name: p.name,
      path: p.path,
      sections: p.sections.map(indexOf).filter((id) => Boolean(id)),
      seo: {
        title: "",
        description: "",
        keywords: "",
        ogImage: "",
        index: true
      }
    };
  });
}
function createProjectFromTemplate(input) {
  const tpl2 = input.template ?? getTemplate(input.templateId);
  if (!tpl2) throw new Error(`Unknown template: ${input.templateId}`);
  const brand = { ...defaultBrand(), ...input.brand };
  const info = {
    name: input.name,
    client: input.client,
    category: input.category ?? tpl2.category,
    description: input.description ?? "",
    audience: input.audience ?? "",
    language: input.language ?? "en"
  };
  const sectionTypes = input.sections && input.sections.length > 0 ? tpl2.defaultSections.filter((t) => input.sections.includes(t)) : tpl2.defaultSections;
  const sections = buildSections(sectionTypes, brand, { ...tpl2.defaultContent ?? {}, ...input.content }, tpl2.sectionVariants);
  const pages = buildPages(tpl2, sections, tpl2.pages);
  const features = TEMPLATE_FEATURES.map((f) => ({
    id: f.id,
    enabled: (input.features ?? tpl2.features).includes(f.id)
  }));
  const now = (/* @__PURE__ */ new Date()).toISOString();
  const baseTheme = themeFromPreset(tpl2.themePresetId);
  const theme = deepMerge(baseTheme, {
    ...input.theme ?? {},
    /* Arabic projects default to an Arabic typeface pair */
    ...input.language === "ar" ? { fonts: { heading: "kufi", body: "kufi", arabic: "kufi" } } : {}
  });
  const config = {
    projectInfo: info,
    brand,
    theme,
    pages,
    sections,
    features,
    templateId: tpl2.id
  };
  return {
    id: uid(),
    config,
    status: input.status ?? "draft",
    createdAt: now,
    updatedAt: now,
    createdFrom: tpl2.id
  };
}
function duplicateProject(project) {
  const copy2 = structuredClone(project);
  copy2.id = uid();
  copy2.config.projectInfo.name = `${project.config.projectInfo.name} (Copy)`;
  copy2.config.projectInfo.client = "";
  copy2.config.brand = { ...copy2.config.brand, businessName: "" };
  copy2.status = "draft";
  copy2.createdAt = (/* @__PURE__ */ new Date()).toISOString();
  copy2.updatedAt = copy2.createdAt;
  copy2.createdFrom = project.createdFrom;
  return copy2;
}

